scenarios:[{level:'Expert',score:15,text:'useEffect에서 API 호출, 로딩/에러/성공 3가지 상태 관리, cleanup까지 설명.'},{level:'Mid',score:8,text:'API 호출은 하지만 로딩/에러 처리가 부족.'},{level:'Low',score:0,text:'API 호출 경험이 없거나 기본 패턴을 모름.'}],
